    var a = scanner.nextInt()
    var b = scanner.nextInt()
    var c = scanner.nextInt()
    var d = scanner.nextInt()

    var max = a
    if (c < max) max = c
    if (d < max) max = d

    var x = 256 * max

    a -= max
    c -= max
    d -= max

    max = a
    if (b < max) max = b

    x += 32 * max

    println(x)
